import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IAttachmentFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFile";
import typia from "typia";

export async function test_api_create_article_with_valid_complete_information(
  connection: api.IConnection,
): Promise<void> {
  // Prepare complete, valid article creation data
  const file: IAttachmentFile.ICreate = {
    name: "announcement-image",
    extension: "jpg",
    url: "https://company.com/uploads/announcement-image.jpg",
  };
  const input: IBbsArticle.ICreate = {
    writer: "employee.john",
    format: "md",
    title: "2025 Annual General Meeting",
    body: "We are pleased to announce the date and agenda for the AGM. See attachment for schedule.",
    files: [file],
    password: "meeting_secret_2025",
  };

  // Create the new article
  const created = await api.functional.bbs.articles.post(connection, { body: input });
  typia.assert<IBbsArticle>(created);

  // Validate main article fields
  TestValidator.predicate("article id must be uuid")(
    typeof created.id === "string" && created.id.length > 0,
  );
  TestValidator.equals("writer should match")(input.writer)(created.writer);

  // Article must have at least one snapshot
  TestValidator.predicate("should have at least one snapshot")(
    Array.isArray(created.snapshots) && created.snapshots.length > 0,
  );
  const snap = created.snapshots[0];
  TestValidator.equals("title should match")(input.title)(snap.title);
  TestValidator.equals("body should match")(input.body)(snap.body);
  TestValidator.equals("format should match")(input.format)(snap.format);
  TestValidator.equals("files should match")<IAttachmentFile.ICreate[]>(input.files)(snap.files);

  // Confirm persistence by fetching by ID
  const fetched = await api.functional.bbs.articles.getById(connection, { id: created.id });
  typia.assert<IBbsArticle>(fetched);
  TestValidator.equals("fetched id match")(created.id)(fetched.id);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import typia from "typia";

export async function test_api_create_article_with_missing_required_fields(connection: api.IConnection): Promise<void> {
  const validArticle: IBbsArticle.ICreate = {
    writer: "tester",
    title: "Valid Title",
    body: "Some content",
    format: "md",
    password: "supersecret",
    files: []
  };

  // Helper to generate variants missing required fields
  const cases: { name: string; input: Partial<IBbsArticle.ICreate> }[] = [
    {
      name: "missing_title",
      input: { ...validArticle, title: undefined as any },
    },
    {
      name: "missing_body",
      input: { ...validArticle, body: undefined as any },
    },
    {
      name: "missing_password",
      input: { ...validArticle, password: undefined as any },
    },
    {
      name: "missing_all_required",
      input: {
        writer: validArticle.writer,
        format: validArticle.format,
        files: [],
      },
    },
  ];

  for (const testCase of cases) {
    await TestValidator.error(`Creating article with ${testCase.name} should fail`)(
      () =>
        api.functional.bbs.articles.post(connection, {
          body: testCase.input as IBbsArticle.ICreate,
        })
    );
  }
}

