  TestValidator.equals("fetched body matches input")(createInput.body)(fetchedSnapshot.body);
  TestValidator.equals("fetched format matches input")(createInput.format)(fetchedSnapshot.format);
  TestValidator.equals("fetched files matches input")(createInput.files)(fetchedSnapshot.files);

  // Edge case: test empty body (if API allows)
