    TestValidator.predicate("pagination current >= 0")(() => page.pagination.current >= 0);
    TestValidator.predicate("pagination limit >= 0")(() => page.pagination.limit >= 0);
    TestValidator.predicate("pagination records >= 0")(() => page.pagination.records >= 0);
    TestValidator.predicate("pagination pages >= 0")(() => page.pagination.pages >= 0);

