      password
    }
  });
  // Article 2: includes keyword in body
  await api.functional.bbs.articles.post(connection, {
    body: {
      writer: targetWriter,
      format: "txt",
      title: "Beta unrelated",
      body: `This body contains the ${keyword} for search testing.`,
      files: [],
      password
    }
  });
  // Article 3: does NOT include keyword
  await api.functional.bbs.articles.post(connection, {
    body: {
      writer: "otherUser",
      format: "txt",
      title: "A different topic",
      body: "Nothing relevant here.",
      files: [],
      password
    }
  });
  // Article 4: includes keyword but different user
  await api.functional.bbs.articles.post(connection, {
    body: {
      writer: "thirdPerson",
      format: "txt",
      title: `Topic about ${keyword}`,
      body: "Random details.",
      files: [],
      password
    }
  });

  // 2. Compose search/filter for keyword with most recent sort
  const request: IBbsArticle.IRequest = {
    search: { title_or_body: keyword },
    sort: ["-created_at"],
    limit: 20,
    page: 0
  };

  // 3. Request list
  const result = await api.functional.bbs.articles.patch(connection, { body: request });
  typia.assert<IPageIBbsArticle.ISummary>(result);

  // 4. Validate - only includes articles with keyword in title/body
  const resultIds = result.data.map((a) => a.id);
  TestValidator.predicate("All results match keyword")(() =>
    result.data.every(article =>
      article.title.includes(keyword) || (article as any).body?.includes(keyword)
    )
  );
  // 5. Validate descending order by created_at
  TestValidator.predicate("Sorted by most recent")(() => {
    for (let i = 1; i < result.data.length; ++i) {
      if (result.data[i - 1].created_at < result.data[i].created_at)
        return false;
    }
    return true;
  });
  // 6. Validate types
  result.data.forEach(item => typia.assert<IBbsArticle.ISummary>(item));

  // 7. Edge case: search for impossible keyword (should get empty)
  const nonexistResult = await api.functional.bbs.articles.patch(connection, {
    body: {
      search: { title_or_body: "no-such-keyword-xyzzz" },
      sort: ["-created_at"],
      limit: 10,
      page: 0
    }
  });
  typia.assert<IPageIBbsArticle.ISummary>(nonexistResult);
  TestValidator.equals("Empty result for nonexisting keyword")<IBbsArticle.ISummary[]> ([])(nonexistResult.data);
}

