export async function test_api_list_articles_with_special_character_search(
  connection: api.IConnection,
): Promise<void> {
  // Utility for easy content creation
  function articleData(obj: Partial<IBbsArticle.ICreate>): IBbsArticle.ICreate {
    return {
      writer: obj.writer!,
      format: obj.format || "txt",
      title: obj.title!,
      body: obj.body!,
      files: obj.files || ([] as IAttachmentFile.ICreate[]),
      password: obj.password || "P@ssw0rd!",
    };
  }

  // Diverse test articles
  const samples = [
    {
      writer: "emoji_user",
      title: "Emoji in title 😀",
      body: "What a wonderful day! 😎",
      searchWord: "😀",
    },
    {
      writer: "hashtag_user",
      title: "#trending Hashtag",
      body: "Discussing #openai tech...",
      searchWord: "#openai",
    },
    {
      writer: "multilang_user",
      title: "한글 제목",
      body: "다국어 지원 내용입니다. こんにちは世界！",
      searchWord: "こんにちは世界",
    },
    {
      writer: "accent_user",
      title: "Résumé d'études",
      body: "Accents améliorent la clarté.",
      searchWord: "Résumé",
    },
  ];

  // Step 1: Create all articles
  const createdArticles: IBbsArticle[] = [];
  for (const s of samples) {
    const created = await api.functional.bbs.articles.post(connection, {
      body: articleData({
        writer: s.writer,
        title: s.title,
        body: s.body,
      }),
    });
    typia.assert<IBbsArticle>(created);
    createdArticles.push(created);
  }

  // Step 2: Search, verify match
  for (let i = 0; i < samples.length; ++i) {
    const s = samples[i];
    const req: IBbsArticle.IRequest = {
      search: { title_or_body: s.searchWord },
      limit: 10,
      page: 0,
    };
    const result = await api.functional.bbs.articles.patch(connection, { body: req });
    typia.assert<IPageIBbsArticle.ISummary>(result);
    const matching = result.data.find((a) => a.id === createdArticles[i].id);
    TestValidator.predicate(`Should find article with special term: ${s.searchWord}`)(!!matching);
  }

  // Step 3: Negative search (should be empty)
  const nonsense = "!n0_Ma7ch££$✨";
  const negRes = await api.functional.bbs.articles.patch(connection, {
    body: { search: { title_or_body: nonsense }, limit: 10, page: 0 },
  });
  typia.assert<IPageIBbsArticle.ISummary>(negRes);
