import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IPageIBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticle";
import typia from "typia";

export async function test_api_list_abridged_articles_with_default_pagination(connection: api.IConnection): Promise<void> {
  // 1. Prepare default request - no search or pagination parameters
  const req: IBbsArticle.IRequest = {};

  // 2. Call the PATCH /bbs/articles/abridges endpoint
  const page = await api.functional.bbs.articles.abridges.patch(connection, { body: req });

  // 3. Assert type safety of the response
  typia.assert<IPageIBbsArticle.IAbridge>(page);

  // 4. Check pagination object structure & sensible defaults
  const pagination = page.pagination;
  TestValidator.predicate("pagination current page >= 0")(() => pagination.current >= 0);
  TestValidator.predicate("pagination limit >= 0")(() => pagination.limit >= 0);
  TestValidator.predicate("pagination records >= 0")(() => pagination.records >= 0);
  TestValidator.predicate("pagination pages >= 0")(() => pagination.pages >= 0);

  // 5. Data array must be defined
  const data = page.data;
  TestValidator.predicate("data array defined")(() => Array.isArray(data));

  // 6. If we have abridged articles, validate structure of first entry
  if (data.length > 0) {
    const first = data[0];
    typia.assert<IBbsArticle.IAbridge>(first);
    TestValidator.predicate("abridged article has id")(() => typeof first.id === "string" && !!first.id);
    TestValidator.predicate("abridged article has writer")(() => typeof first.writer === "string" && !!first.writer);
    TestValidator.predicate("abridged article has title")(() => typeof first.title === "string" && !!first.title);
    TestValidator.predicate("abridged article has body")(() => typeof first.body === "string");
    TestValidator.predicate("abridged article has format")(() => first.format === "txt" || first.format === "md" || first.format === "html");
    TestValidator.predicate("abridged article has files array")(() => Array.isArray(first.files));
    TestValidator.predicate("abridged article created_at")(() => typeof first.created_at === "string");
    TestValidator.predicate("abridged article updated_at")(() => typeof first.updated_at === "string");
  }
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IPageIBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticle";
import typia from "typia";

export async function test_list_abridged_articles_with_search_keyword(connection: api.IConnection): Promise<void> {
  // Step 1: Create some articles
  const keyword = "project-xyz";
  const articlesToCreate: IBbsArticle.ICreate[] = [
    {
      writer: "alice",
      format: "txt",
      title: `Progress on ${keyword}`,
      body: `Here is the current progress for ${keyword}`,
      files: [],
      password: "password1"
    },
    {
      writer: "bob",
      format: "md",
      title: "General Discussion",
      body: "Some unrelated topic",
      files: [],
      password: "password2"
    },
    {
      writer: "carol",
      format: "txt",
      title: "Announcement",
      body: `The ${keyword} has launched!`,
      files: [],
      password: "password3"
    },
    {
      writer: "dan",
      format: "html",
      title: "Random Thoughts",
      body: "This has nothing to do with projects.",
      files: [],
      password: "password4"
    }
  ];
  const createdArticleIds: string[] = [];
  for (const input of articlesToCreate) {
    const created = await api.functional.bbs.articles.post(connection, { body: input });
    typia.assert<IBbsArticle>(created);
    createdArticleIds.push(created.id);
  }

  // Step 2: Query for abridged articles using keyword in title or body
  const request: IBbsArticle.IRequest = {
    search: {
      title_or_body: keyword
    },
    limit: 10,
    page: 0
  };
  const result = await api.functional.bbs.articles.abridges.patch(connection, { body: request });
  typia.assert<IPageIBbsArticle.IAbridge>(result);

  // Step 3: Verify only matching articles are returned
  const actualIds = result.data.map(article => article.id);
  // Only articles 0 and 2 should match the search
  const expectedMatches = [0, 2].map(i => createdArticleIds[i]);
  TestValidator.predicate("Should only return articles with keyword in title or body")(
    actualIds.length === expectedMatches.length &&
    expectedMatches.every(id => actualIds.includes(id))
  );

  // Step 4: The non-matching article IDs should not appear
  const unexpected = [1, 3].map(i => createdArticleIds[i]);
  TestValidator.predicate("Should not return unrelated articles")(
    actualIds.every(id => !unexpected.includes(id))
  );

  // Step 5: Validate pagination structure
  TestValidator.predicate("Pagination structure is valid")(
    typeof result.pagination.current === "number" &&
    typeof result.pagination.limit === "number" &&
    typeof result.pagination.records === "number" &&
    typeof result.pagination.pages === "number"
  );

  // Optionally check the required fields are highlighted in summary
  result.data.forEach(article => {
    TestValidator.predicate("Should include title containing keyword or body containing keyword")(
      article.title.includes(keyword) || article.body.includes(keyword)
    );
    typia.assert<IBbsArticle.IAbridge>(article);
  });
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IPageIBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticle";
import typia from "typia";

export async function test_list_abridged_articles_with_valid_date_range_filter(connection: api.IConnection): Promise<void> {
  // Step 1: Create three articles, each with controlled creation times (simulate with current time gap if no setting possible)
  const now = new Date();
  const oneDay = 24 * 60 * 60 * 1000;

  // articles A and B: within range, C: outside (too early)
  const createdArticles: IBbsArticle[] = [];
  for (let i = 0; i < 3; ++i) {
    const article = await api.functional.bbs.articles.post(connection, {
      body: {
        writer: `user${i}`,
        format: "txt",
        title: `Test article ${i}`,
        body: `This is the body of article ${i}`,
        files: [],
        password: "password123"
      }
    });
    typia.assert<IBbsArticle>(article);
    createdArticles.push(article);
  }

  // Sort articles by actual creation date
  createdArticles.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

  // Now select a date range that should only include the last two articles
  const startDate = createdArticles[1].created_at; // Start from article 1
  const endDate = createdArticles[2].created_at;   // End at newest article (2)

  // Step 2: Use PATCH on /bbs/articles/abridges with the from/to filter
  const requestBody: IBbsArticle.IRequest = {
    search: {
      from: startDate,
      to: endDate,
    }
  };
  const result = await api.functional.bbs.articles.abridges.patch(connection, {
    body: requestBody
  });
  typia.assert<IPageIBbsArticle.IAbridge>(result);

  // Step 3: Validate each returned record is within the filter range
  for (const abridged of result.data) {
    const createdAt = new Date(abridged.created_at).getTime();
    const start = new Date(startDate).getTime();
    const end = new Date(endDate).getTime();
    TestValidator.predicate(`article created_at is within filter range`)(createdAt >= start && createdAt <= end);
  }

  // Step 4: Pagination meta checks (basic type assertion)
  typia.assert<IPageIBbsArticle.IAbridge["pagination"]>(result.pagination);

  // Step 5: Validate that only expected articles are included
  const expectedIds = createdArticles
    .filter(a => (new Date(a.created_at).getTime() >= new Date(startDate).getTime()) && (new Date(a.created_at).getTime() <= new Date(endDate).getTime()))
    .map(a => a.id)
    .sort();
  const resultIds = result.data.map(a => a.id).sort();
  TestValidator.equals("filtered IDs match", undefined)(expectedIds)(resultIds);
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IAttachmentFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFile";
import { IPageIBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticle";
import typia from "typia";

export async function test_api_list_abridged_articles_with_custom_sorting(connection: api.IConnection): Promise<void> {
    // Prepare articles with different writers and times
    const now = Date.now();
    const baseFiles: IAttachmentFile.ICreate[] = [];

    const articlesInput: IBbsArticle.ICreate[] = [
        {
            writer: "alice",
            format: "md",
            title: "First Article",
            body: "Content A",
            files: baseFiles,
            password: "pw1",
        },
        {
            writer: "bob",
            format: "txt",
            title: "Second Article",
            body: "Content B",
            files: baseFiles,
            password: "pw2",
        },
    ];
    // Create articles
    const createdArticles: IBbsArticle[] = [];
    for (const input of articlesInput) {
        const created = await api.functional.bbs.articles.post(connection, { body: input });
        typia.assert<IBbsArticle>(created);
        createdArticles.push(created);
        // Sleep 10ms to ensure unique created_at for sorting
        await new Promise((res) => setTimeout(res, 10));
    }

    // -- 1. Sort by created_at descending (-- newest first)
    const resultByCreatedDesc = await api.functional.bbs.articles.abridges.patch(connection, {
        body: {
            sort: ["-created_at"],
            limit: 10,
        },
    });
    typia.assert<IPageIBbsArticle.IAbridge>(resultByCreatedDesc);
    const abridgesDesc = resultByCreatedDesc.data;
    TestValidator.predicate("sorted desc by created_at")(abridgesDesc.length >= 2);
    for (let i = 1; i < abridgesDesc.length; ++i) {
        TestValidator.predicate(`created_at[${i-1}] >= created_at[${i}]`)(
            abridgesDesc[i - 1].created_at >= abridgesDesc[i].created_at
        );
    }

    // -- 2. Sort by writer ascending
    const resultByWriterAsc = await api.functional.bbs.articles.abridges.patch(connection, {
        body: {
            sort: ["+writer"],
            limit: 10,
        },
    });
    typia.assert<IPageIBbsArticle.IAbridge>(resultByWriterAsc);
    const abridgesByWriter = resultByWriterAsc.data;
    TestValidator.predicate("sorted asc by writer")(abridgesByWriter.length >= 2);
    for (let i = 1; i < abridgesByWriter.length; ++i) {
        TestValidator.predicate(`writer[${i-1}] <= writer[${i}]`)(
            abridgesByWriter[i - 1].writer <= abridgesByWriter[i].writer
        );
    }

    // -- 3. Validate pagination structure
    typia.assert<IPageIBbsArticle.IAbridge['pagination']>(resultByWriterAsc.pagination);
    typia.assert<IPageIBbsArticle.IAbridge['pagination']>(resultByCreatedDesc.pagination);

    // -- 4. Negative: pass unsupported sort, expect default (no error, fallback behavior)
    await TestValidator.error("unsupported sort should fail or fallback")(
        async () => {
            await api.functional.bbs.articles.abridges.patch(connection, {
                body: { sort: ["+not_a_field"] as any, limit: 10 },
            });
        }
    );
}

import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IPageIBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticle";
