export async function test_api_bbs_articles_abridges_patch(
  connection: api.IConnection,
): Promise<void> {
  // Set a large limit for maximum records per page
  const largeLimit = 1000;
  const request: IBbsArticle.IRequest = {
    limit: largeLimit,
    page: 0,
    // Optionally add a sort for deterministic ordering
    sort: ["-created_at"]
  };

  // Send the PATCH request to fetch abridged articles
  const response = await api.functional.bbs.articles.abridges.patch(connection, { body: request });

  // Validate response type
  typia.assert<IPageIBbsArticle.IAbridge>(response);
  // Validate the page limit settings
  TestValidator.equals("limit must match largeLimit")(
    largeLimit
  )(response.pagination.limit);
  // The response data length should not be greater than limit
  TestValidator.predicate(
    "response.data.length must be <= largeLimit"
  )(() => response.data.length <= largeLimit);
  // Each data element must be valid IBbsArticle.IAbridge
  for (const article of response.data) {
    typia.assert<IBbsArticle.IAbridge>(article);
  }
  // Pagination current page must be 0
  TestValidator.equals("current page should be 0")(0)(response.pagination.current);
