import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import typia from "typia";

export async function test_list_abridged_articles_with_invalid_filter_or_sort(
  connection: api.IConnection
): Promise<void> {
  // 1. Invalid sort field
  const invalidSortRequest: IBbsArticle.IRequest = {
    sort: ["+nonexistent_field" as any],
    page: 0,
    limit: 10
  };
  await TestValidator.httpError("invalid sort field")(400)(async () => {
    await api.functional.bbs.articles.abridges.patch(connection, { body: invalidSortRequest });
  });

  // 2. Invalid search field
  const invalidSearchRequest: IBbsArticle.IRequest = {
    // @ts-expect-error purposely insert an invalid search field
    search: { wrongField: "wrong" },
    page: 0,
    limit: 10
  };
  await TestValidator.error("invalid search field, type error")(() =>
    typia.assert<IBbsArticle.IRequest>(invalidSearchRequest)
  );
  // Optionally try sending to API
  await TestValidator.httpError("invalid search field API")(400)(async () => {
    // @ts-ignore runtime, try anyway
    await api.functional.bbs.articles.abridges.patch(connection, { body: invalidSearchRequest });
  });

  // 3. Date filter range: 'from' > 'to'
  const now = new Date();
  const future = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 365); // +1 year
  const past = new Date(now.getTime() - 1000 * 60 * 60 * 24);
  const badDateRangeRequest: IBbsArticle.IRequest = {
    search: {
      from: future.toISOString(),
      to: past.toISOString()
    },
    page: 0,
    limit: 10
  };
  await TestValidator.httpError("bad date range filter")(400, 422)(async () => {
    await api.functional.bbs.articles.abridges.patch(connection, { body: badDateRangeRequest });
  });

  // 4. Invalid sort format (object or wrong string)
  const weirdSortRequest: IBbsArticle.IRequest = {
    sort: ["writer:desc" as any],
    page: 0,
    limit: 10
  };
  await TestValidator.httpError("invalid sort directive")(400)(async () => {
    await api.functional.bbs.articles.abridges.patch(connection, { body: weirdSortRequest });
  });
}

