import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IPageIBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticle";
import typia from "typia";

export async function test_list_abridged_articles_with_boundary_values(connection: api.IConnection): Promise<void> {
  // 1. Zero page number
  const reqZeroPage: IBbsArticle.IRequest = { page: 0, limit: 10 };
  const resZeroPage = await api.functional.bbs.articles.abridges.patch(connection, { body: reqZeroPage });
  typia.assert<IPageIBbsArticle.IAbridge>(resZeroPage);
  TestValidator.predicate("zero page should return data")(() => Array.isArray(resZeroPage.data));

  // 2. Negative page and limit (expect error or graceful correction)
  const reqNeg: IBbsArticle.IRequest = { page: -1 as any, limit: -10 as any };
  await TestValidator.httpError("negative page and limit should cause error or be corrected")(400, 422)(
    async () => {
      await api.functional.bbs.articles.abridges.patch(connection, { body: reqNeg });
    }
  );

  // 3. Very high page size (limit)
  const reqHighLimit: IBbsArticle.IRequest = { page: 1, limit: 10000 as any };
  const resHighLimit = await api.functional.bbs.articles.abridges.patch(connection, { body: reqHighLimit });
  typia.assert<IPageIBbsArticle.IAbridge>(resHighLimit);
  TestValidator.predicate("high limit should not crash")( () => Array.isArray(resHighLimit.data));

  // 4. Empty (whitespace) search terms
  const reqEmptySearch: IBbsArticle.IRequest = {
    search: { title: "   ", body: "" },
    page: 1,
    limit: 5,
  };
  const resEmptySearch = await api.functional.bbs.articles.abridges.patch(connection, { body: reqEmptySearch });
  typia.assert<IPageIBbsArticle.IAbridge>(resEmptySearch);

  // 5. Very long string search (title/body >255 chars)
  const longString = "a".repeat(300);
  const reqLongSearch: IBbsArticle.IRequest = {
    search: { title: longString, body: longString },
    page: 1,
    limit: 5,
  };
  // Accepts error OR empty result OR valid search
  try {
    const resLongSearch = await api.functional.bbs.articles.abridges.patch(connection, { body: reqLongSearch });
    typia.assert<IPageIBbsArticle.IAbridge>(resLongSearch);
    TestValidator.predicate("should return data array even for long search str")(() => Array.isArray(resLongSearch.data));
  } catch (err) {
    // Acceptable: either error (validation), or empty result, but not server crash
    TestValidator.predicate("should throw error for invalid search str")(() => !!err);
  }
}

