import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import typia from "typia";

export async function test_get_article_by_valid_id_when_article_exists(connection: api.IConnection): Promise<void> {
  // Step 1. Create a new article
  const initialArticle: IBbsArticle.ICreate = {
    writer: "alice.emp",
    title: "Work Guidelines",
    body: "Initial guidelines content.",
    format: "txt",
    files: [],
    password: "editSecret1234",
  };
  const created = await api.functional.bbs.articles.post(connection, { body: initialArticle });
  typia.assert<IBbsArticle>(created);

  // Step 2. Update the article twice, storing the update data for validation
  const update1: IBbsArticle.IUpdate = {
    title: "Work Guidelines (v2)",
    body: "Updated guidelines content (clarified steps).",
    format: "txt",
    files: [],
    password: "editSecret1234",
  };
  const snap1 = await api.functional.bbs.articles.putById(connection, { id: created.id, body: update1 });
  typia.assert<IBbsArticle.ISnapshot>(snap1);

  const update2: IBbsArticle.IUpdate = {
    title: "Work Guidelines (Final)",
    body: "Finalized version after team review.",
    format: "txt",
    files: [],
    password: "editSecret1234",
  };
  const snap2 = await api.functional.bbs.articles.putById(connection, { id: created.id, body: update2 });
  typia.assert<IBbsArticle.ISnapshot>(snap2);

  // Step 3. Retrieve article by id
  const gotten = await api.functional.bbs.articles.getById(connection, { id: created.id });
  typia.assert<IBbsArticle>(gotten);

  // Step 4-1. Check top-level properties
  TestValidator.equals("writer")<string>(created.writer)(gotten.writer);
  TestValidator.equals("id")<string>(created.id)(gotten.id);
  TestValidator.equals("created_at")<string>(created.created_at)(gotten.created_at);
  TestValidator.predicate("snapshots length is 3")(() => gotten.snapshots.length === 3);

  // Step 4-2. Check historical snapshots in order (initial + 2 updates)
  // First snapshot (creation):
  TestValidator.equals("initial snapshot.title")<string>(initialArticle.title)(gotten.snapshots[0].title);
  TestValidator.equals("initial snapshot.body")<string>(initialArticle.body)(gotten.snapshots[0].body);
  TestValidator.equals("initial snapshot.format")<string>(initialArticle.format)(gotten.snapshots[0].format);

  // Second snapshot (first update):
  TestValidator.equals("update1 snapshot.title")<string>(update1.title)(gotten.snapshots[1].title);
  TestValidator.equals("update1 snapshot.body")<string>(update1.body)(gotten.snapshots[1].body);
  TestValidator.equals("update1 snapshot.format")<string>(update1.format)(gotten.snapshots[1].format);

  // Third snapshot (second update):
  TestValidator.equals("update2 snapshot.title")<string>(update2.title)(gotten.snapshots[2].title);
  TestValidator.equals("update2 snapshot.body")<string>(update2.body)(gotten.snapshots[2].body);
  TestValidator.equals("update2 snapshot.format")<string>(update2.format)(gotten.snapshots[2].format);
}

