import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import typia from "typia";

export async function test_get_article_with_access_restriction_unauthenticated_user(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create a valid article as an authenticated (system) user (simulate session/auth required)
  // Setup a connection that is authenticated (simulate logged-in)
  const authConnection: api.IConnection = {
    ...connection,
    // Add any auth tokens or cookie here if required for the API
    headers: {
      ...connection.headers,
      // "Authorization": "Bearer MOCK_TOKEN", // Use if API expects it (could be empty if public)
    },
  };
  const createInput: IBbsArticle.ICreate = {
    writer: "test-user-unauth",
    format: "txt",
    title: "Private Article for Auth Test",
    body: "This is a protected article.",
    files: [],
    password: "TestPassword123!",
  };
  const article = await api.functional.bbs.articles.post(authConnection, { body: createInput });
  typia.assert<IBbsArticle>(article);

  // Step 2: Attempt to access the article WITHOUT authentication (simulate guest user: no cookies/session/tokens)
  // Usually, removing authorization headers is sufficient for most implementations
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(Object.entries(connection.headers ?? {}).filter(([k]) => k.toLowerCase() !== "authorization")),
    // Remove session/cookie if used in headers also
  };

  // Step 3: Should receive an Unauthorized (401) or appropriate forbidden response
  await TestValidator.httpError("Unauthenticated users should be denied access to article detail")(401, 403)(async () => {
    await api.functional.bbs.articles.getById(unauthenticatedConnection, { id: article.id });
  });
}

