import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import typia from "typia";

export async function test_get_article_when_multiple_snapshots_exist(connection: api.IConnection): Promise<void> {
    // Step 1: Create initial article with known values
    const password = "securePw123!";
    const initialInput: IBbsArticle.ICreate = {
        writer: "audit-user1",
        format: "txt",
        title: "Announcement v1",
        body: "Original content.",
        files: [],
        password
    };
    const article = await api.functional.bbs.articles.post(connection, { body: initialInput });
    typia.assert<IBbsArticle>(article);

    // Step 2: Apply multiple well-differentiated updates
    const updates: IBbsArticle.IUpdate[] = [
        {
            title: "Announcement v2",
            body: "First major modification.",
            format: "md",
            files: [],
            password
        },
        {
            title: "Announcement v3",
            body: "Final policy update.",
            format: "html",
            files: [],
            password
        }
    ];
    for (const update of updates) {
        await api.functional.bbs.articles.putById(connection, { id: article.id, body: update });
    }

    // Step 3: Retrieve the article and check all snapshots
    const read = await api.functional.bbs.articles.getById(connection, { id: article.id });
    typia.assert<IBbsArticle>(read);
    TestValidator.equals("id")(article.id)(read.id);
    TestValidator.equals("writer")(initialInput.writer)(read.writer);
    TestValidator.predicate("snapshots length should be 3")(() => read.snapshots.length === 3);

    // Step 4: Validate contents of each snapshot
    const expectedSnapshots = [
        {
            title: initialInput.title,
            body: initialInput.body,
            format: initialInput.format
        },
        {
            title: updates[0].title,
            body: updates[0].body,
            format: updates[0].format
        },
        {
            title: updates[1].title,
            body: updates[1].body,
            format: updates[1].format
        },
    ];
    read.snapshots.forEach((snapshot, idx) => {
        typia.assert<IBbsArticle.ISnapshot>(snapshot);
        TestValidator.equals(`snapshot[${idx}].title`)(expectedSnapshots[idx].title)(snapshot.title);
        TestValidator.equals(`snapshot[${idx}].body`)(expectedSnapshots[idx].body)(snapshot.body);
        TestValidator.equals(`snapshot[${idx}].format`)(expectedSnapshots[idx].format)(snapshot.format);
        TestValidator.equals(`snapshot[${idx}].files`)([] as typeof snapshot.files)(snapshot.files);
    });

    // Step 5: Timestamps strictly increase
    for (let i = 0; i < read.snapshots.length - 1; ++i) {
        const cur = new Date(read.snapshots[i].created_at).getTime();
        const next = new Date(read.snapshots[i + 1].created_at).getTime();
        TestValidator.predicate(`snapshots[${i}].created_at < snapshots[${i + 1}].created_at`)(() => cur < next);
    }
}

