  const maxFiles = 10;
  const largeFileAttachment: IAttachmentFile.ICreate = {
    name: "Attachment-" + "x".repeat(240),
    extension: "pdf",
    url: "https://test-server.com/uploads/" + "largefile_" + "y".repeat(200) + ".pdf"
  };
  const allowedAttachments: IAttachmentFile.ICreate[] = Array.from({ length: maxFiles }, (_, idx) => ({
