  // Step 4: Attempt invalid update exceeding the attachment count (simulate 1 over limit)
  const excessiveAttachments: IAttachmentFile.ICreate[] = Array.from({ length: maxFiles + 1 }, (_, idx) => ({
    ...largeFileAttachment,
    name: `Attachment${idx + 1}${largeFileAttachment.name.slice(10)}`
  }));
