    format: "md",
    title: "Annual Technical Report (Too Many Attachments)",
    body: "This update tries to upload more attachments than allowed.",
    files: excessiveAttachments,
    password: articleCreateInput.password,
  };
  await TestValidator.error("Exceeding file count should fail")(() =>
    api.functional.bbs.articles.putById(connection, {
      id: article.id,
      body: articleUpdateExceed,
    })
  );

  // Step 5: Clean up - erase article
  await api.functional.bbs.articles.eraseById(connection, {
    id: article.id,
    body: { password: articleCreateInput.password }
  });
}

