export async function test_create_comment_with_valid_data_on_existing_article(connection: api.IConnection): Promise<void> {
  // Step 1: Create a new article to post the comment on
  const articleInput: IBbsArticle.ICreate = {
    writer: "employee_1",
    format: "md",
    title: "How to request vacation days",
    body: "Example announcement about company policies.",
    files: [],
    password: "pass12345"
  };
  const article: IBbsArticle = await api.functional.bbs.articles.post(connection, { body: articleInput });
  typia.assert<IBbsArticle>(article);

  // Step 2: Prepare comment input (with file)
  const file: IAttachmentFile.ICreate = {
    name: "policy-guide",
    extension: "pdf",
    url: "https://resource.domain.com/files/policy-guide.pdf"
  };
  const commentInput: IBbsArticleComment.ICreate = {
    writer: "employee_1",
    format: "md",
    body: "Thanks for clarifying the policy. Here is a guide for reference.",
    files: [file],
    password: "comment-pass-123"
  };

  // Step 3: Create the comment
