export async function test_list_comments_with_standard_pagination_and_no_filters(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create an article
  const articleInput: IBbsArticle.ICreate = {
    writer: "employee_001",
    format: "txt",
    title: "Test Article for Comment List Pagination",
    body: "This is a test article used to validate comments pagination.",
    files: [],
    password: "articlepw123!",
  };
  const article = await api.functional.bbs.articles.post(connection, { body: articleInput });
  typia.assert<IBbsArticle>(article);

  // Step 2: Create 15 comments
  const COMMENTS_TO_CREATE = 15;
  const commentIds: string[] = [];
  for (let i = 0; i < COMMENTS_TO_CREATE; ++i) {
    const commentInput: IBbsArticleComment.ICreate = {
      writer: `employee_${i % 3 + 1}`,
      format: "txt",
      body: `Comment body #${i + 1}`,
      files: [],
      password: `commentpw${i + 1}`,
    };
    const comment = await api.functional.bbs.articles.comments.postByArticleid(connection, {
      articleId: article.id,
      body: commentInput,
    });
    typia.assert<IBbsArticleComment>(comment);
    commentIds.push(comment.id);
  }

  // Step 3: Fetch first page (default typical settings)
  const PAGE_LIMIT = 10;
  const page0 = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
    articleId: article.id,
    body: {
      page: 0,
      limit: PAGE_LIMIT,
    },
  });
  typia.assert<IPageIBbsArticleComment>(page0);

  // expectations for page 0
  TestValidator.equals("first page current", undefined)(page0.pagination.current)(0);
  TestValidator.equals("first page limit", undefined)(page0.pagination.limit)(PAGE_LIMIT);
  TestValidator.equals("first page length", undefined)(page0.data.length)(PAGE_LIMIT);
  for (const comment of page0.data) typia.assert<IBbsArticleComment>(comment);

  // Step 4: Fetch second page (page 1) for the rest (should be 5 comments)
  const page1 = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
    articleId: article.id,
    body: {
      page: 1,
      limit: PAGE_LIMIT,
    },
  });
  typia.assert<IPageIBbsArticleComment>(page1);
  TestValidator.equals("second page current", undefined)(page1.pagination.current)(1);
  TestValidator.equals("second page limit", undefined)(page1.pagination.limit)(PAGE_LIMIT);
  TestValidator.equals("second page length", undefined)(page1.data.length)(5);
  for (const comment of page1.data) typia.assert<IBbsArticleComment>(comment);

  // Step 5: Fetch page 2 (should be empty)
  const page2 = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
    articleId: article.id,
    body: {
      page: 2,
      limit: PAGE_LIMIT,
    },
  });
  typia.assert<IPageIBbsArticleComment>(page2);
  TestValidator.equals("third page current", undefined)(page2.pagination.current)(2);
  TestValidator.equals("third page length", undefined)(page2.data.length)(0);
