import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IBbsArticleComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticleComment";
import { IPageIBbsArticleComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBbsArticleComment";
import { IAttachmentFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFile";
import typia from "typia";

export async function test_api_list_comments_with_custom_sorting_and_pagination_settings(connection: api.IConnection): Promise<void> {
    // 1. Create an article to comment on
    const password = "pw1234";
    const articleInput: IBbsArticle.ICreate = {
        writer: "alice",
        format: "txt",
        title: "Sorting and Pagination Test",
        body: "Test content for custom sorting/pagination",
        files: [] as IAttachmentFile.ICreate[],
        password
    };
    const article = await api.functional.bbs.articles.post(connection, { body: articleInput });
    typia.assert<IBbsArticle>(article);

    // 2. Add 75 comments with increasing created_at (simulate chronological order).   
    const commentPassword = "cpass";
    const totalComments = 75;
    const commentIds: string[] = [];
    for (let i = 0; i < totalComments; ++i) {
        const commentInput: IBbsArticleComment.ICreate = {
            writer: `user${i % 3}`,
            format: "txt",
            body: `Comment body ${i}`,
            files: [] as IAttachmentFile.ICreate[],
            password: commentPassword
        };
        const comment = await api.functional.bbs.articles.comments.postByArticleid(connection, {
            articleId: article.id,
            body: commentInput
        });
        typia.assert<IBbsArticleComment>(comment);
        commentIds.push(comment.id);
    }

    // 3. Retrieve the first page, 50 per page, ascending order (oldest first)
    const reqAsc: IBbsArticleComment.IRequest = {
        sort: ["+created_at"],
        page: 1,
        limit: 50
    };
    const pageAsc = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
        articleId: article.id,
        body: reqAsc
    });
    typia.assert<IPageIBbsArticleComment>(pageAsc);
    TestValidator.predicate("limit should be 50 or less")(
        pageAsc.data.length <= 50
    );
    TestValidator.equals("pagination info exists")(
        true
    )(!!pageAsc.pagination);
    // Check that sorting is ascending (oldest first)
    for (let i = 1; i < pageAsc.data.length; ++i) {
        const prev = pageAsc.data[i - 1];
        const curr = pageAsc.data[i];
        TestValidator.predicate(`ascending by created_at at index ${i}`)(
            new Date(prev.created_at) <= new Date(curr.created_at)
        );
    }
    // Page 2, check next 25
    const reqPage2: IBbsArticleComment.IRequest = {
        sort: ["+created_at"],
        page: 2,
        limit: 50
    };
    const page2 = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
        articleId: article.id,
        body: reqPage2
    });
    typia.assert<IPageIBbsArticleComment>(page2);
    TestValidator.predicate("limit on page 2 should be 25")(
        page2.data.length === 25
    );
    // 4. Retrieve first page, 50 per page, descending (newest first)
    const reqDesc: IBbsArticleComment.IRequest = {
        sort: ["-created_at"],
        page: 1,
        limit: 50
    };
    const pageDesc = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
        articleId: article.id,
        body: reqDesc
    });
    typia.assert<IPageIBbsArticleComment>(pageDesc);
    for (let i = 1; i < pageDesc.data.length; ++i) {
        const prev = pageDesc.data[i - 1];
        const curr = pageDesc.data[i];
        TestValidator.predicate(`descending by created_at at index ${i}`)(
            new Date(prev.created_at) >= new Date(curr.created_at)
        );
    }
    // 5. Edge case: No comments for a new article
    const emptyArticleInput: IBbsArticle.ICreate = {
        writer: "no_comment_user",
        format: "txt",
        title: "Article no comments",
        body: "No comments here",
        files: [] as IAttachmentFile.ICreate[],
        password
    };
    const emptyArticle = await api.functional.bbs.articles.post(connection, { body: emptyArticleInput });
    typia.assert<IBbsArticle>(emptyArticle);
    const emptyPatch = await api.functional.bbs.articles.comments.patchByArticleid(connection, {
        articleId: emptyArticle.id,
        body: {
            page: 1,
            limit: 50,
            sort: ["+created_at"]
        } as IBbsArticleComment.IRequest
    });
    typia.assert<IPageIBbsArticleComment>(emptyPatch);
    TestValidator.equals("data is [] if no comments")([] as IBbsArticleComment[])(emptyPatch.data);
    TestValidator.equals("pagination info for empty list")(
        true
    )(!!emptyPatch.pagination);
}

