import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IBbsArticleComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticleComment";
import typia from "typia";

export async function test_api_retrieve_comment_details_when_comment_exists(connection: api.IConnection): Promise<void> {
    // 1. Create test article
    const articleInput: IBbsArticle.ICreate = {
        writer: "employee1",
        format: "txt",
        title: "Transparency and Audit Test",
        body: "Discussion on comment transparency.",
        files: [],
        password: "test-password-article"
    };
    const article = await api.functional.bbs.articles.post(connection, { body: articleInput });
    typia.assert<IBbsArticle>(article);

    // 2. Create test comment for that article
    const commentInput: IBbsArticleComment.ICreate = {
        writer: "employee2",
        format: "txt",
        body: "This is the original comment.",
        files: [],
        password: "test-password-comment"
    };
    const comment = await api.functional.bbs.articles.comments.postByArticleid(connection, {
        articleId: article.id,
        body: commentInput,
    });
    typia.assert<IBbsArticleComment>(comment);

    // 3. Retrieve (GET) the comment details with full snapshots
    const read = await api.functional.bbs.articles.comments.getByArticleidAndId(connection, {
        articleId: article.id,
        id: comment.id
    });
    typia.assert<IBbsArticleComment>(read);

    // 4. Validate data integrity and snapshot history
    // Should have at least one snapshot (the creation)
    TestValidator.predicate("at least one snapshot exists")(
        read.snapshots.length >= 1
    );

    // Current snapshot should match what we created
    const latestSnapshot = read.snapshots[read.snapshots.length - 1];
    TestValidator.equals("latest snapshot body")(
        commentInput.body
    )(latestSnapshot.body);
    TestValidator.equals("latest snapshot format")(
        commentInput.format
    )(latestSnapshot.format);
    TestValidator.equals("latest snapshot title always undefined for comments")(
        undefined
    )((latestSnapshot as any).title);
    // Files array matches
    TestValidator.equals("files array")(
        commentInput.files
    )(latestSnapshot.files);
    // Writer and parent_id should match
    TestValidator.equals("parent_id is null for new top-level comment")(
        null
    )(read.parent_id as any);
    // Created_at should be an ISO string (validate with typia tag)
    TestValidator.predicate("created_at is valid ISO string")(
        typeof read.created_at === "string" && !isNaN(Date.parse(read.created_at))
    );
}

