import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { IBbsArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticle";
import { IBbsArticleComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IBbsArticleComment";
import { IAttachmentFile } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachmentFile";
import typia from "typia";

export async function test_api_update_comment_with_valid_data(connection: api.IConnection): Promise<void> {
    // Step 1: Create the article
    const articleInput: IBbsArticle.ICreate = {
        writer: "test.employee",
        format: "txt",
        title: "Initial Article Title",
        body: "This is the article body.",
        files: [] as IAttachmentFile.ICreate[],
        password: "articlepw123",
    };
    const article = await api.functional.bbs.articles.post(connection, { body: articleInput });
    typia.assert<IBbsArticle>(article);

    // Step 2: Create the comment
    const commentPassword = "commentpw456";
    const commentInput: IBbsArticleComment.ICreate = {
        writer: "test.employee",
        format: "md",
        body: "Original comment body.",
        files: [] as IAttachmentFile.ICreate[],
        password: commentPassword,
    };
    const comment = await api.functional.bbs.articles.comments.postByArticleid(connection, {
        articleId: article.id,
        body: commentInput
    });
    typia.assert<IBbsArticleComment>(comment);

    // Step 3: Update the comment with new content and new attachment
    const updatedFiles: IAttachmentFile.ICreate[] = [
        {
            name: "important-image",
            extension: "png",
            url: "https://example.com/files/image1.png"
        }
    ];
    const updateInput: IBbsArticleComment.IUpdate = {
        body: "This is an updated comment with more clarity and a file.",
        format: "md",
        files: updatedFiles,
        password: commentPassword,
    };
    const updatedSnapshot = await api.functional.bbs.articles.comments.putByArticleidAndId(connection, {
        articleId: article.id,
        id: comment.id,
        body: updateInput
    });
    typia.assert<IBbsArticleComment.ISnapshot>(updatedSnapshot);

    // Step 4: Fetch the comment and check snapshots
    const fetched = await api.functional.bbs.articles.comments.getByArticleidAndId(connection, {
        articleId: article.id,
        id: comment.id
    });
    typia.assert<IBbsArticleComment>(fetched);

    // It must have at least 2 snapshots (original + update)
    TestValidator.predicate("at least 2 snapshots")(fetched.snapshots.length >= 2);

    // The latest snapshot should match the update
    const lastSnapshot = fetched.snapshots[fetched.snapshots.length - 1];
    TestValidator.equals("latest body matches")(updateInput.body)(lastSnapshot.body);
    TestValidator.equals("latest format matches")(updateInput.format)(lastSnapshot.format);
    TestValidator.equals("latest files matches")(
        updateInput.files
    )(lastSnapshot.files);

    // Old snapshot is still present (original)
    const firstSnapshot = fetched.snapshots[0];
    TestValidator.equals("original body matches")(commentInput.body)(firstSnapshot.body);
    TestValidator.equals("original files matches")(commentInput.files)(firstSnapshot.files);
}

