import { TestValidator } from "@nestia/e2e";
import api from "@ORGANIZATION/PROJECT-api";
import { ISystem } from "@ORGANIZATION/PROJECT-api/lib/structures/ISystem";
import typia from "typia";

export async function test_api_get_system_information_under_high_load(connection: api.IConnection): Promise<void> {
  // Number of quick successive calls simulating monitoring during load
  const REPEAT_COUNT = 5;
  // Delay (ms) between calls — simulates user or automation polling
  const DELAY_MS = 20;

  for (let i = 0; i < REPEAT_COUNT; ++i) {
    let system: ISystem | null = null;
    try {
      system = await api.functional.monitors.system.get(connection);
    } catch (err) {
      // Allow a clear fail if unable to connect or endpoint failure
      TestValidator.error(`System info call should not error during load [iteration ${i}]`)(() => { throw err; });
      continue; // Defensive: proceed to next iteration
    }
    typia.assert<ISystem>(system);
    TestValidator.predicate(`System UID must be a number [iteration ${i}]`)(typeof system.uid === "number");
    TestValidator.predicate(`System should have version [iteration ${i}]`)(!!system.package.version && typeof system.package.version === "string");
    TestValidator.predicate(`System commit branch exists [iteration ${i}]`)(!!system.commit.branch && typeof system.commit.branch === "string");
    TestValidator.predicate(`System created_at is string [iteration ${i}]`)(typeof system.created_at === "string");
    // Optional: For debugging, you may log system values here if needed
    if (i < REPEAT_COUNT - 1) await new Promise(res => setTimeout(res, DELAY_MS));
  }
}

